cd /workspace && cat > src/main.rs << 'EOF'
use std::env;
use std::fs;
use std::io::{self, Read};
use std::process;

mod parser;
mod transformer;
mod highlighter;

use parser::Parser;
use transformer::Transformer;
use highlighter::Highlighter;

const VERSION: &str = "4.3.1";

#[derive(Debug)]
struct Options {
    suggest: bool,
    syntax: bool,
    syntax_suggest: bool,
    transform: bool,
    check: bool,
    replace: bool,
    help: bool,
    version: bool,
    files: Vec<String>,
}

impl Default for Options {
    fn default() -> Self {
        Options {
            suggest: false,
            syntax: false,
            syntax_suggest: true,  // default
            transform: false,
            check: false,
            replace: false,
            help: false,
            version: false,
            files: Vec::new(),
        }
    }
}

fn print_help() {
    eprintln!("Shellharden: The corrective bash syntax highlighter.

Usage:
\tshellharden [options] [files]
\tcat files | shellharden [options] ''

Shellharden is a syntax highlighter and a tool to semi-automate the rewriting
of scripts to ShellCheck conformance, mainly focused on quoting.

The default mode of operation is like `cat`, but with syntax highlighting in
foreground colors and suggestive changes in background colors.

Options:
\t--suggest         Output a colored diff suggesting changes.
\t--syntax          Output syntax highlighting with ANSI colors.
\t--syntax-suggest  Diff with syntax highlighting (default mode).
\t--transform       Output suggested changes.
\t--check           No output; exit with 2 if changes are suggested.
\t--replace         Replace file contents with suggested changes.
\t--                Don't treat further arguments as options.
\t-h|--help         Show help text.
\t--version         Show version.

The changes suggested by Shellharden inhibits word splitting and indirect
pathname expansion. This will make your script ShellCheck compliant in terms of
quoting. Whether your script will work afterwards is a different question:
If your script was using those features on purpose, it obviously won't anymore!

Every script is possible to write without using word splitting or indirect
pathname expansion, but it may involve doing things differently.
See the accompanying file how_to_do_things_safely_in_bash.md or online:
https://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md
");
}

fn parse_args() -> (Options, Option<String>) {
    let args: Vec<String> = env::args().collect();
    let mut opts = Options::default();
    let mut i = 1;
    let mut stop_options = false;
    let mut last_error = None;

    while i < args.len() {
        let arg = &args[i];

        if stop_options {
            opts.files.push(arg.clone());
        } else if arg == "--" {
            stop_options = true;
        } else if arg == "--help" || arg == "-h" {
            opts.help = true;
        } else if arg == "--version" {
            opts.version = true;
        } else if arg == "--suggest" {
            opts.syntax_suggest = false;
            opts.suggest = true;
        } else if arg == "--syntax" {
            opts.syntax_suggest = false;
            opts.syntax = true;
        } else if arg == "--syntax-suggest" {
            opts.syntax_suggest = true;
            opts.suggest = false;
            opts.syntax = false;
        } else if arg == "--transform" {
            opts.syntax_suggest = false;
            opts.suggest = false;
            opts.syntax = false;
            opts.transform = true;
        } else if arg == "--check" {
            opts.syntax_suggest = false;
            opts.suggest = false;
            opts.syntax = false;
            opts.transform = false;
            opts.check = true;
        } else if arg == "--replace" {
            opts.replace = true;
        } else if arg.starts_with("--") {
            last_error = Some(format!("{}: No such option.", arg));
            i += 1;
            continue;
        } else if arg.starts_with("-") && arg != "-" {
            last_error = Some(format!("{}: No such option.", arg));
            i += 1;
            continue;
        } else {
            opts.files.push(arg.clone());
        }
        i += 1;
    }

    (opts, last_error)
}

fn read_input(opts: &Options) -> io::Result<String> {
    if opts.files.is_empty() {
        // Read from stdin
        let mut buffer = String::new();
        io::stdin().read_to_string(&mut buffer)?;
        Ok(buffer)
    } else if opts.files.len() == 1 && opts.files[0].is_empty() {
        // Empty string means stdin
        let mut buffer = String::new();
        io::stdin().read_to_string(&mut buffer)?;
        Ok(buffer)
    } else {
        // Read from files
        let mut content = String::new();
        for (idx, file) in opts.files.iter().enumerate() {
            let file_content = fs::read_to_string(file)?;
            content.push_str(&file_content);
            if idx < opts.files.len() - 1 {
                content.push('\n');
            }
        }
        Ok(content)
    }
}

fn main() {
    let (opts, error) = parse_args();

    if let Some(err) = error {
        eprintln!("{}", err);
        process::exit(1);
    }

    if opts.help {
        print_help();
        process::exit(0);
    }

    if opts.version {
        println!("{}", VERSION);
        process::exit(0);
    }

    let input = match read_input(&opts) {
        Ok(content) => content,
        Err(e) => {
            eprintln!("Error reading input: {}", e);
            process::exit(1);
        }
    };

    // Parse the shell script
    let parser = Parser::new(&input);
    let ast = parser.parse();

    // Apply transformations if needed
    let (transformed, has_changes) = if opts.transform || opts.check || opts.suggest || opts.syntax_suggest {
        let transformer = Transformer::new();
        transformer.transform(&ast)
    } else {
        (ast.clone(), false)
    };

    // Handle different output modes
    if opts.check {
        // No output, just exit code
        if has_changes {
            process::exit(2);
        } else {
            process::exit(0);
        }
    } else if opts.transform {
        // Output transformed version without colors
        print!("{}", transformed.to_string());
    } else if opts.suggest {
        // Output with suggestions highlighted
        let highlighter = Highlighter::new();
        print!("{}", highlighter.highlight_with_suggestions(&ast, &transformed));
    } else if opts.syntax {
        // Output with syntax coloring only
        let highlighter = Highlighter::new();
        print!("{}", highlighter.highlight_syntax(&ast));
    } else {
        // Default: syntax-suggest
        let highlighter = Highlighter::new();
        print!("{}", highlighter.highlight_with_suggestions(&ast, &transformed));
    }

    if opts.replace && !opts.files.is_empty() {
        // Write back to file
        for file in &opts.files {
            if let Err(e) = fs::write(file, transformed.to_string()) {
                eprintln!("Error writing to {}: {}", file, e);
                process::exit(1);
            }
        }
    }
}
EOF

