            let file_content = fs::read_to_string(file)?;
            content.push_str(&file_content);
            if idx < opts.files.len() - 1 {
                content.push('\n');
            }
        }
        Ok(content)
    }
}

fn main() {
    let (opts, error) = parse_args();

    if let Some(err) = error {
        eprintln!("{}", err);
        process::exit(1);
    }

    if opts.help {
        print_help();
        process::exit(0);
    }

    if opts.version {
        println!("{}", VERSION);
        process::exit(0);
    }

    let input = match read_input(&opts) {
        Ok(content) => content,
        Err(e) => {
            eprintln!("Error reading input: {}", e);
            process::exit(1);
        }
    };

    // Parse the shell script
    let parser = Parser::new(&input);
    let ast = parser.parse();

    // Apply transformations if needed
    let (transformed, has_changes) = if opts.transform || opts.check || opts.suggest || opts.syntax_suggest {
        let transformer = Transformer::new();
        transformer.transform(&ast)
    } else {
        (ast.clone(), false)
    };

    // Handle different output modes
    if opts.check {
        // No output, just exit code
        if has_changes {
            process::exit(2);
        } else {
            process::exit(0);
        }
    } else if opts.transform {
        // Output transformed version without colors
        print!("{}", transformed.to_string());
    } else if opts.suggest {
        // Output with suggestions highlighted
        let highlighter = Highlighter::new();
        print!("{}", highlighter.highlight_with_suggestions(&ast, &transformed));
    } else if opts.syntax {
        // Output with syntax coloring only
        let highlighter = Highlighter::new();
        print!("{}", highlighter.highlight_syntax(&ast));
    } else {
        // Default: syntax-suggest
        let highlighter = Highlighter::new();
        print!("{}", highlighter.highlight_with_suggestions(&ast, &transformed));
    }

    if opts.replace && !opts.files.is_empty() {
        // Write back to file
        for file in &opts.files {
            if let Err(e) = fs::write(file, transformed.to_string()) {
                eprintln!("Error writing to {}: {}", file, e);
                process::exit(1);
            }
        }
    }
}
