use crate::parser::ASTNode;
use regex::Regex;

pub struct Transformer {
}

impl Transformer {
    pub fn new() -> Self {
        Transformer {}
    }

    pub fn transform(&self, ast: &ASTNode) -> (ASTNode, bool) {
        let mut new_ast = ast.clone();
        let mut has_changes = false;

        // Process each line
        for child in &mut new_ast.children {
            let (new_line, changed) = self.transform_line(&child.value);
            child.value = new_line;
            if changed {
                has_changes = true;
            }
        }

        (new_ast, has_changes)
    }

    pub fn transform_line(&self, line: &str) -> (String, bool) {
        let mut result = line.to_string();
        let mut changed = false;

        // Replace $* with "$@"
        if result.contains("$*") {
            let new_result = result.replace("$*", "\"$@\"");
            if new_result != result {
                changed = true;
                result = new_result;
            }
        }

        (result, changed)
    }
}
