use regex::Regex;
use std::collections::HashMap;

pub struct Transformer {
    patterns: Vec<(Regex, String)>,
}

impl Transformer {
    pub fn new() -> Self {
        Transformer {
            patterns: Vec::new(),
        }
    }

    pub fn transform(&self, input: &str) -> (String, bool) {
        let mut output = String::new();
        let mut has_changes = false;

        for line in input.lines() {
            let (transformed_line, line_changed) = self.transform_line(line);
            output.push_str(&transformed_line);
            output.push('\n');
            if line_changed {
                has_changes = true;
            }
        }

        // Remove the final newline if the input didn't have one
        if !input.ends_with('\n') && output.ends_with('\n') {
            output.pop();
        }

        (output, has_changes)
    }

    fn transform_line(&self, line: &str) -> (String, bool) {
        let mut result = line.to_string();
        let original = result.clone();
        let mut changed = false;

        // Track context as we scan through the line
        result = self.apply_transformations(&result, &mut changed);

        (result, changed)
    }

    fn apply_transformations(&self, line: &str, changed: &mut bool) -> String {
        let mut result = String::new();
        let mut i = 0;
        let chars: Vec<char> = line.chars().collect();
        let len = chars.len();

        while i < len {
            let ch = chars[i];

            // Skip comments
            if ch == '#' && !self.is_in_string(&chars, i) {
                result.push_str(&line[i..]);
                break;
            }

            // Handle strings
            if ch == '"' && (i == 0 || chars[i - 1] != '\\') {
                let (string_content, end_pos) = self.read_double_quoted_string(&chars, i);
                result.push_str(&string_content);
                i = end_pos;
                continue;
            }

            if ch == '\'' && (i == 0 || chars[i - 1] != '\\') {
                let (string_content, end_pos) = self.read_single_quoted_string(&chars, i);
                result.push_str(&string_content);
                i = end_pos;
                continue;
            }

            // Handle variables
            if ch == '$' && (i == 0 || chars[i - 1] != '\\') {
                let (var_str, end_pos, _was_transformed) = self.handle_variable(&chars, i, line);
                result.push_str(&var_str);
                if _was_transformed {
                    *changed = true;
                }
                i = end_pos;
                continue;
            }

            result.push(ch);
            i += 1;
        }

        result
    }

    fn is_in_string(&self, chars: &[char], pos: usize) -> bool {
        let mut in_single = false;
        let mut in_double = false;

        for i in 0..pos {
            if chars[i] == '\'' && (i == 0 || chars[i - 1] != '\\') {
                if !in_double {
                    in_single = !in_single;
                }
            }
            if chars[i] == '"' && (i == 0 || chars[i - 1] != '\\') {
                if !in_single {
                    in_double = !in_double;
                }
            }
        }

        in_single || in_double
    }

    fn read_double_quoted_string(&self, chars: &[char], start: usize) -> (String, usize) {
        let mut result = String::from("\"");
        let mut i = start + 1;

        while i < chars.len() {
            if chars[i] == '"' && chars[i - 1] != '\\' {
                result.push('"');
                return (result, i + 1);
            }
            result.push(chars[i]);
            i += 1;
        }

        (result, i)
    }

    fn read_single_quoted_string(&self, chars: &[char], start: usize) -> (String, usize) {
        let mut result = String::from("'");
        let mut i = start + 1;

        while i < chars.len() {
            if chars[i] == '\'' && chars[i - 1] != '\\' {
                result.push('\'');
                return (result, i + 1);
            }
            result.push(chars[i]);
            i += 1;
        }

        (result, i)
    }

    fn handle_variable(&self, chars: &[char], start: usize, _line: &str) -> (String, usize, bool) {
        let mut i = start + 1;
        let mut var_name = String::new();
        let mut transformed = false;

        // Handle ${ }
        if i < chars.len() && chars[i] == '{' {
            let (var_str, end_pos, was_transformed) = self.handle_brace_expansion(chars, start);
            return (var_str, end_pos, was_transformed);
        }

        // Handle $(...)
        if i < chars.len() && chars[i] == '(' {
            let (var_str, end_pos) = self.handle_command_substitution(chars, start);
