use std::collections::VecDeque;

pub struct Transformer;

#[derive(Debug, Clone, Copy, PartialEq)]
enum Context {
    Normal,
    DoubleQuote,
    SingleQuote,
    Backquote,
    DollarParen,
    DollarBrace,
    Arithmetic,
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum TokenType {
    Variable,
    CommandSubst,
    Text,
    Whitespace,
    String,
}

impl Transformer {
    pub fn new() -> Self {
        Transformer
    }

    pub fn transform(&self, input: &str) -> (String, bool) {
        let mut output = String::new();
        let mut has_changes = false;

        // Process line by line, keeping track if we're in a multi-line construct
        let lines: Vec<&str> = input.lines().collect();
        for line in lines {
            let (transformed_line, line_changed) = self.transform_line(line);
            output.push_str(&transformed_line);
            output.push('\n');
            if line_changed {
                has_changes = true;
            }
        }

        // Remove the final newline if the input didn't have one
        if !input.ends_with('\n') && output.ends_with('\n') {
            output.pop();
        }

        (output, has_changes)
    }

    fn transform_line(&self, line: &str) -> (String, bool) {
        if line.is_empty() {
            return (line.to_string(), false);
        }

        let original = line.to_string();
        let mut result = String::new();
        let mut changed = false;
        let mut i = 0;
        let chars: Vec<char> = line.chars().collect();

        while i < chars.len() {
            let ch = chars[i];

            // Handle strings
            if ch == '"' {
                let (quoted_str, new_i) = self.read_double_quoted_string(&chars, i);
                result.push_str(&quoted_str);
                i = new_i;
                continue;
            }

            if ch == '\'' {
                let (quoted_str, new_i) = self.read_single_quoted_string(&chars, i);
                result.push_str(&quoted_str);
                i = new_i;
                continue;
            }

            // Handle variables
            if ch == '$' {
                let (var_str, new_i, var_changed) = self.handle_dollar(&chars, i, line);
                result.push_str(&var_str);
                i = new_i;
                if var_changed {
                    changed = true;
                }
                continue;
            }

            // Handle comments
            if ch == '#' && self.can_be_comment(&chars, i) {
                result.push_str(&line[i..]);
                break;
            }

            result.push(ch);
            i += 1;
        }

        (result, changed)
    }

    fn can_be_comment(&self, chars: &[char], pos: usize) -> bool {
        // Check if we're not in a string
        let mut in_single = false;
        let mut in_double = false;

        for i in 0..pos {
            match chars[i] {
                '\'' if !in_double => in_single = !in_single,
                '"' if !in_single => in_double = !in_double,
                _ => {}
            }
        }

        !in_single && !in_double
    }

    fn read_double_quoted_string(&self, chars: &[char], start: usize) -> (String, usize) {
        let mut result = String::from("\"");
        let mut i = start + 1;

        while i < chars.len() {
            if chars[i] == '\\' && i + 1 < chars.len() {
                result.push(chars[i]);
                result.push(chars[i + 1]);
                i += 2;
                continue;
            }

            if chars[i] == '"' {
                result.push('"');
                return (result, i + 1);
            }

            result.push(chars[i]);
            i += 1;
        }

        (result, i)
    }

    fn read_single_quoted_string(&self, chars: &[char], start: usize) -> (String, usize) {
        let mut result = String::from("'");
        let mut i = start + 1;

        while i < chars.len() {
            if chars[i] == '\'' {
                result.push('\'');
                return (result, i + 1);
            }

            result.push(chars[i]);
            i += 1;
        }

        (result, i)
    }

    fn handle_dollar(&self, chars: &[char], start: usize, line: &str) -> (String, usize, bool) {
        if start + 1 >= chars.len() {
            return ("$".to_string(), start + 1, false);
        }

        let next = chars[start + 1];

        // Handle ${...}
        if next == '{' {
            return self.handle_dollar_brace(chars, start, line);
        }

        // Handle $(...)
        if next == '(' {
            return self.handle_dollar_paren(chars, start, line);
        }

        // Handle $((arithmetic))
        if next == '(' && start + 2 < chars.len() && chars[start + 2] == '(' {
            return self.handle_arithmetic(chars, start, line);
        }

        // Handle simple $var or $1 etc
        self.handle_simple_var(chars, start, line)
    }

    fn handle_simple_var(&self, chars: &[char], start: usize, line: &str) -> (String, usize, bool) {
        let mut i = start + 1;
        let mut var_name = String::new();

        if i >= chars.len() {
            return ("$".to_string(), i, false);
        }

        // Get variable name
        if chars[i].is_ascii_digit() {
            var_name.push(chars[i]);
            i += 1;
        } else if chars[i].is_alphabetic() || chars[i] == '_' {
            while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '_') {
                var_name.push(chars[i]);
                i += 1;
            }
        } else if "?!#*@-".contains(chars[i]) {
            var_name.push(chars[i]);
            i += 1;
        } else {
            return ("$".to_string(), i, false);
        }

        let var_str = format!("${}", var_name);
        let should_quote = self.should_quote_variable(&var_name, line, start);

        if should_quote && !self.is_already_quoted(line, start) && !self.in_assignment(line, start) {
            (format!("\"${}\"", var_name), i, true)
        } else {
            (var_str, i, false)
        }
    }

    fn handle_dollar_brace(&self, chars: &[char], start: usize, _line: &str) -> (String, usize, bool) {
        let mut result = String::from("${");
        let mut i = start + 2;
        let mut depth = 1;

        while i < chars.len() && depth > 0 {
            if chars[i] == '{' {
                depth += 1;
            } else if chars[i] == '}' {
                depth -= 1;
            }

            result.push(chars[i]);
            i += 1;
        }

        (result, i, false)
    }

    fn handle_dollar_paren(&self, chars: &[char], start: usize, _line: &str) -> (String, usize, bool) {
        let mut result = String::from("$(");
        let mut i = start + 2;
        let mut depth = 1;

        while i < chars.len() && depth > 0 {
            if chars[i] == '(' && (i == 0 || chars[i - 1] != '\\') {
                depth += 1;
            } else if chars[i] == ')' && (i == 0 || chars[i - 1] != '\\') {
                depth -= 1;
            }

            result.push(chars[i]);
            i += 1;
        }

        (result, i, false)
    }

    fn handle_arithmetic(&self, chars: &[char], start: usize, _line: &str) -> (String, usize, bool) {
        let mut result = String::from("$((");
        let mut i = start + 3;
        let mut depth = 2;

        while i < chars.len() && depth > 0 {
            if chars[i] == '(' {
                depth += 1;
            } else if chars[i] == ')' {
                depth -= 1;
                if depth == 0 {
                    result.push(')');
                    result.push(')');
                    i += 1;
                    break;
                }
            }

            result.push(chars[i]);
            i += 1;
        }

        (result, i, false)
    }

    fn should_quote_variable(&self, var_name: &str, _line: &str, _pos: usize) -> bool {
        // Special variables that don't need quoting
        matches!(var_name, "?" | "!" | "#" | "$" | "0")
    }

    fn is_already_quoted(&self, line: &str, pos: usize) -> bool {
        // Check if the $ is already inside quotes
        if pos == 0 {
            return false;
        }

        let mut in_single = false;
        let mut in_double = false;

        for i in 0..pos {
            let ch = line.chars().nth(i).unwrap();
            match ch {
                '\'' if !in_double => in_single = !in_single,
                '"' if !in_single => in_double = !in_double,
                _ => {}
            }
        }

        in_single || in_double
    }

    fn in_assignment(&self, line: &str, pos: usize) -> bool {
        // Check if we're on the right side of an assignment (x=$var)
        // Look backwards for '='
        let before = &line[..pos];
        if let Some(eq_pos) = before.rfind('=') {
            // Check if this is actually an assignment operator, not ==
            if eq_pos > 0 && before.chars().nth(eq_pos - 1) == Some('!') {
                return false; // This is !=
            }
            if eq_pos + 1 < before.len() && before.chars().nth(eq_pos + 1) == Some('=') {
                return false; // This is ==
            }

            // Check if there's nothing but whitespace between = and our position
            let after_eq = &before[eq_pos + 1..];
            return after_eq.trim().is_empty();
        }

        false
    }
}
