            let (transformed_line, line_changed) = self.transform_line(line);
            output.push_str(&transformed_line);
            output.push('\n');
            if line_changed {
                has_changes = true;
            }
        }

        // Remove the final newline if the input didn't have one
        if !input.ends_with('\n') && output.ends_with('\n') {
            output.pop();
        }

        (output, has_changes)
    }

    fn transform_line(&self, line: &str) -> (String, bool) {
        if line.is_empty() {
            return (line.to_string(), false);
        }

        let mut result = String::new();
        let mut changed = false;
        let mut i = 0;
        let chars: Vec<char> = line.chars().collect();

        while i < chars.len() {
            let ch = chars[i];

            // Handle strings
            if ch == '"' {
                let (quoted_str, new_i) = self.read_double_quoted_string(&chars, i);
                result.push_str(&quoted_str);
                i = new_i;
                continue;
            }

            if ch == '\'' {
                let (quoted_str, new_i) = self.read_single_quoted_string(&chars, i);
                result.push_str(&quoted_str);
                i = new_i;
                continue;
            }

            // Handle backtick command substitution
            if ch == '`' {
                let (backtick_str, new_i) = self.read_backtick_string(&chars, i);
                result.push_str(&backtick_str);
                i = new_i;
                continue;
            }

            // Handle variables
            if ch == '$' {
                let (var_str, new_i, var_changed) = self.handle_dollar(&chars, i, line);
                result.push_str(&var_str);
                i = new_i;
                if var_changed {
                    changed = true;
                }
                continue;
            }

            // Handle comments
            if ch == '#' && self.can_be_comment(&chars, i) {
                result.push_str(&line[i..]);
                break;
            }

            result.push(ch);
            i += 1;
        }

        (result, changed)
    }

    fn can_be_comment(&self, chars: &[char], pos: usize) -> bool {
        // Check if we're not in a string
        let mut in_single = false;
        let mut in_double = false;

        for i in 0..pos {
            match chars[i] {
                '\'' if !in_double => in_single = !in_single,
                '"' if !in_single => in_double = !in_double,
                _ => {}
            }
        }

        !in_single && !in_double
    }

    fn read_double_quoted_string(&self, chars: &[char], start: usize) -> (String, usize) {
        let mut result = String::from("\"");
        let mut i = start + 1;

        while i < chars.len() {
            if chars[i] == '\\' && i + 1 < chars.len() {
                result.push(chars[i]);
                result.push(chars[i + 1]);
                i += 2;
                continue;
            }

            if chars[i] == '"' {
                result.push('"');
                return (result, i + 1);
            }

            result.push(chars[i]);
            i += 1;
        }

        (result, i)
    }

    fn read_single_quoted_string(&self, chars: &[char], start: usize) -> (String, usize) {
        let mut result = String::from("'");
        let mut i = start + 1;

        while i < chars.len() {
            if chars[i] == '\'' {
                result.push('\'');
                return (result, i + 1);
            }

            result.push(chars[i]);
            i += 1;
        }

        (result, i)
    }

    fn read_backtick_string(&self, chars: &[char], start: usize) -> (String, usize) {
        let mut result = String::from("`");
        let mut i = start + 1;

        while i < chars.len() {
            if chars[i] == '`' && (i == 0 || chars[i - 1] != '\\') {
                result.push('`');
                return (result, i + 1);
            }
            if chars[i] == '\\' && i + 1 < chars.len() && chars[i + 1] == '`' {
                result.push(chars[i]);
                result.push(chars[i + 1]);
                i += 2;
                continue;
            }

            result.push(chars[i]);
            i += 1;
        }

        (result, i)
    }

    fn handle_dollar(&self, chars: &[char], start: usize, line: &str) -> (String, usize, bool) {
        if start + 1 >= chars.len() {
            return ("$".to_string(), start + 1, false);
        }

        let next = chars[start + 1];

        // Handle ${...}
        if next == '{' {
            return self.handle_dollar_brace(chars, start, line);
        }

        // Handle $(...)
        if next == '(' {
            // Check for $((...)) arithmetic
            if start + 2 < chars.len() && chars[start + 2] == '(' {
                return self.handle_arithmetic(chars, start, line);
            }
            return self.handle_dollar_paren(chars, start, line);
        }

        // Handle simple $var or $1 etc
        self.handle_simple_var(chars, start, line)
    }

    fn handle_simple_var(&self, chars: &[char], start: usize, line: &str) -> (String, usize, bool) {
        let mut i = start + 1;
        let mut var_name = String::new();

        if i >= chars.len() {
            return ("$".to_string(), i, false);
        }

        // Get variable name
        if chars[i].is_ascii_digit() {
            var_name.push(chars[i]);
            i += 1;
        } else if chars[i].is_alphabetic() || chars[i] == '_' {
            while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '_') {
                var_name.push(chars[i]);
                i += 1;
            }
        } else if "?!#*@-".contains(chars[i]) {
