        let should_quote = self.should_add_quotes(&var_name, line, start);

        if should_quote && !self.is_already_quoted(line, start) {
            (format!("\"${}\"", var_name), i, true)
        } else {
            (var_str, i, false)
        }
    }

    fn handle_dollar_brace(&self, chars: &[char], start: usize, line: &str) -> (String, usize, bool) {
        let mut result = String::from("${");
        let mut i = start + 2;
        let mut depth = 1;
        let mut inner_start = i;

        while i < chars.len() && depth > 0 {
            if chars[i] == '{' {
                depth += 1;
            } else if chars[i] == '}' {
                depth -= 1;
                if depth == 0 {
                    break;
                }
            }

            result.push(chars[i]);
            i += 1;
        }

        // Extract variable name for quoting decision
        let inner_content: String = chars[inner_start..i].iter().collect();
        let var_name = inner_content.split_whitespace().next().unwrap_or("").split(|c: char| !c.is_alphanumeric() && c != '_').next().unwrap_or("").to_string();

        if i < chars.len() && chars[i] == '}' {
            result.push('}');
            i += 1;
        }

        // Check if should be quoted
        let should_quote = self.should_add_quotes(&var_name, line, start) && !var_name.is_empty();

        if should_quote && !self.is_already_quoted(line, start) {
            (format!("\"{}\"", result), i, true)
        } else {
            (result, i, false)
        }
    }

    fn handle_dollar_paren(&self, chars: &[char], start: usize, line: &str) -> (String, usize, bool) {
        let mut result = String::from("$(");
        let mut i = start + 2;
        let mut depth = 1;

        while i < chars.len() && depth > 0 {
            if chars[i] == '(' {
                depth += 1;
            } else if chars[i] == ')' {
                depth -= 1;
                if depth > 0 {
                    result.push(chars[i]);
                }
            } else {
                result.push(chars[i]);
            }

            i += 1;
        }

        result.push(')');

        // Command substitutions should be quoted
        if !self.is_already_quoted(line, start) {
            (format!("\"{}\"", result), i, true)
        } else {
            (result, i, false)
        }
    }

    fn handle_arithmetic(&self, chars: &[char], start: usize, _line: &str) -> (String, usize, bool) {
        let mut result = String::from("$((");
        let mut i = start + 3;
        let mut depth = 1;

        while i < chars.len() && depth > 0 {
            if chars[i] == '(' {
                depth += 1;
            } else if chars[i] == ')' {
                depth -= 1;
                if depth > 0 {
                    result.push(chars[i]);
                }
            } else {
                result.push(chars[i]);
            }

            i += 1;
        }

        result.push(')');
        result.push(')');

        (result, i, false)
    }

    fn should_add_quotes(&self, var_name: &str, line: &str, pos: usize) -> bool {
        // Variables that should never be quoted
        if matches!(var_name, "?" | "!" | "#" | "$" | "0") {
            return false;
        }

        // In assignments, don't quote
        if self.is_in_assignment(line, pos) {
            return false;
        }

        // In [[ ]] context, don't quote the variable being tested
        if self.is_in_double_bracket(line, pos) {
            return false;
        }

        // In [ ] test, don't quote in some contexts
        if self.is_in_single_bracket(line, pos) {
            return false;
        }

        // Regular variables should be quoted
        true
    }

    fn is_already_quoted(&self, line: &str, pos: usize) -> bool {
        // Check if the $ is already inside quotes
        if pos == 0 {
            return false;
        }

        let mut in_single = false;
        let mut in_double = false;

        for i in 0..pos {
            let ch = line.chars().nth(i).unwrap();
            match ch {
                '\'' if !in_double => in_single = !in_single,
                '"' if !in_single => in_double = !in_double,
                _ => {}
            }
        }

        in_single || in_double
    }

    fn is_in_assignment(&self, line: &str, pos: usize) -> bool {
        // Check if we're on the right side of an assignment (x=$var)
        let before = &line[..pos];
        if let Some(eq_pos) = before.rfind('=') {
            // Check if this is actually an assignment operator, not == or !=
            if eq_pos > 0 {
                let prev = line.chars().nth(eq_pos - 1).unwrap_or(' ');
                if prev == '!' || prev == '=' || prev == '<' || prev == '>' {
                    return false;
                }
            }
            if eq_pos + 1 < line.len() {
                let next = line.chars().nth(eq_pos + 1).unwrap_or(' ');
                if next == '=' {
                    return false;
                }
            }

            // Check if there's nothing but whitespace between = and our position
            let after_eq = &before[eq_pos + 1..];
            return after_eq.chars().all(|c| c.is_whitespace());
        }

        false
    }

    fn is_in_double_bracket(&self, line: &str, pos: usize) -> bool {
        let before = &line[..pos];
        let after = &line[pos..];

        // Simple check: is there [[ before and ]] after?
        before.contains("[[") && after.contains("]]")
    }

    fn is_in_single_bracket(&self, line: &str, pos: usize) -> bool {
        let before = &line[..pos];
        let after = &line[pos..];

        // Simple check: is there [ before and ] after?
        let has_open = before.contains("[ ") || before.contains("[");
        let has_close = after.contains("]");
        has_open && has_close
    }
